package android.os;import java.util.*;import java.util.concurrent.*;public class Handler{public static final Queue<Runnable> jobs=new ConcurrentLinkedQueue<>();private record Delayed(long at,Runnable job){}private static final List<Delayed> delayed=new ArrayList<>();public Handler(Looper ignored){}public boolean post(Runnable task){jobs.add(task);return true;}public boolean postDelayed(Runnable task,long ms){delayed.add(new Delayed(SystemClock.now+ms,task));return true;}public void removeCallbacks(Runnable task){jobs.removeIf(r->r==task);delayed.removeIf(d->d.job()==task);}public void removeCallbacksAndMessages(Object ignored){jobs.clear();delayed.clear();}public static void reset(){jobs.clear();delayed.clear();}public static void advance(long ms){SystemClock.now+=ms;drain();}public static void drain(){while(true){for(var d:new ArrayList<>(delayed))if(d.at()<=SystemClock.now){delayed.remove(d);jobs.add(d.job());}Runnable task=jobs.poll();if(task==null)return;task.run();}}}
